var containsDuplicate = function(nums) {
    const seen = new Set();

    for (const num of nums) {
        // If we already saw this number, it's a duplicate
        if (seen.has(num)) {
            return true;
        }

        // Remember this number
        seen.add(num);
    }

    // No duplicates found
    return false;
};

